pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(_owner != address(0));
        vm.assume(actor != _owner);
        vm.prank(actor);
        bool ok = true;
        try c.setOwner(_owner) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.prank(nonOwner);
        bool reverted;
        try c.setOwner(nonOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (reverted) {
            assertTrue(c.owner() != nonOwner, "owner changed despite revert");
        } else {
            assertTrue(c.owner() == address(this), "owner changed when it should not");
        }
    }
}

