pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, address newOwner) public {
        vm.assume(attacker != address(c).owner);
        vm.prank(attacker);
        bool shouldRevert = attacker != address(c).owner;
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(shouldRevert ? !ok : ok);
    }
}

